import{_ as e,o,c as d,a3 as r}from"./chunks/framework.DsQ8uxR7.js";const u=JSON.parse('{"title":"Konado WebTool","description":"","frontmatter":{},"headers":[],"relativePath":"en/konado_webtool/konado_webtool.md","filePath":"en/konado_webtool/konado_webtool.md","lastUpdated":1777930169000}'),a={name:"en/konado_webtool/konado_webtool.md"};function l(n,t,s,i,c,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="konado-webtool" tabindex="-1">Konado WebTool <a class="header-anchor" href="#konado-webtool" aria-label="Permalink to &quot;Konado WebTool&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Konado WebTool is a plugin that provides web platform development tool support for the Konado project. Since Godot 4.x captures and disables all keyboard shortcuts by default on the web platform, browser DevTools shortcuts (such as F12, F5, etc.) cannot be used normally. This plugin solves this problem by allowing common browser DevTools shortcuts on the web platform, making it easier for developers to debug and develop in a web environment.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Konado WebTool injects JavaScript code on the web platform to release keyboard shortcuts. It will:</p><ol><li>Detect whether the current platform is the web platform</li><li>If it is the web platform and DevTools support is enabled, inject the shortcut handling code</li><li>Dynamically build the list of allowed shortcuts based on configuration</li><li>Listen for keyboard events, prevent default behaviour for allowed shortcuts, thereby passing them through to the browser</li></ol><h3 id="comparison-with-other-solutions" tabindex="-1">Comparison with Other Solutions <a class="header-anchor" href="#comparison-with-other-solutions" aria-label="Permalink to &quot;Comparison with Other Solutions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Solution</th><th>Advantages</th><th>Disadvantages</th></tr></thead><tbody><tr><td>Konado WebTool</td><td>Simple to use, highly configurable, easy to maintain</td><td>No significant disadvantages</td></tr><tr><td>Manual export template modification</td><td>Full control</td><td>High technical demands, requires frequent updates</td></tr><tr><td>Development environment switching</td><td>Can debug on desktop platform</td><td>Cannot capture web platform-specific issues</td></tr></tbody></table><h2 id="supported-browser-shortcuts" tabindex="-1">Supported Browser Shortcuts <a class="header-anchor" href="#supported-browser-shortcuts" aria-label="Permalink to &quot;Supported Browser Shortcuts&quot;">​</a></h2><p>These shortcuts are based on the standard DevTools shortcuts for mainstream browsers (such as Chrome, Firefox, Edge, etc.), referencing official documentation from each browser:</p><ul><li><a href="https://developer.mozilla.org/en-US/docs/Tools/Keyboard_shortcuts" target="_blank" rel="noreferrer">Firefox DevTools</a></li><li><a href="https://learn.microsoft.com/en-us/microsoft-edge/devtools-guide-chromium/shortcuts/" target="_blank" rel="noreferrer">Edge DevTools</a></li><li><a href="https://developer.chrome.com/docs/devtools/shortcuts/" target="_blank" rel="noreferrer">Chrome DevTools</a></li><li><a href="https://webkit.org/web-inspector/keyboard-shortcuts/" target="_blank" rel="noreferrer">Safari DevTools (WebKit)</a></li></ul><table tabindex="0"><thead><tr><th>Shortcut</th><th>Function</th><th>Enable Option</th></tr></thead><tbody><tr><td>F12</td><td>Open DevTools</td><td><code>enable_f12</code></td></tr><tr><td>F5</td><td>Refresh page</td><td><code>enable_f5</code></td></tr><tr><td>F11</td><td>Toggle fullscreen</td><td><code>enable_f11</code></td></tr><tr><td>Ctrl+Shift+I (Win/Linux) / Cmd+Opt+I (Mac)</td><td>Open elements panel</td><td><code>enable_ctrl_shift_i</code></td></tr><tr><td>Ctrl+Shift+J (Win/Linux) / Cmd+Opt+J (Mac)</td><td>Open console</td><td><code>enable_ctrl_shift_j</code></td></tr><tr><td>Ctrl+Shift+C (Win/Linux) / Cmd+Shift+C (Mac)</td><td>Inspect element mode</td><td><code>enable_ctrl_shift_c</code></td></tr><tr><td>Ctrl+U (Win/Linux) / Cmd+U (Mac)</td><td>View page source</td><td><code>enable_ctrl_u</code></td></tr><tr><td>Ctrl+R (Win/Linux) / Cmd+R (Mac)</td><td>Refresh page</td><td><code>enable_ctrl_r</code></td></tr></tbody></table><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to &quot;Configuration Options&quot;">​</a></h2><p>In the auto-loaded <code>KND_WebTool</code> node, you can configure the following properties:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>enable_web_devtool</code></td><td>bool</td><td>true</td><td>Enable web DevTools shortcut passthrough</td></tr><tr><td><code>enable_f12</code></td><td>bool</td><td>true</td><td>Enable F12 shortcut</td></tr><tr><td><code>enable_f5</code></td><td>bool</td><td>true</td><td>Enable F5 shortcut</td></tr><tr><td><code>enable_f11</code></td><td>bool</td><td>true</td><td>Enable F11 shortcut</td></tr><tr><td><code>enable_ctrl_shift_i</code></td><td>bool</td><td>true</td><td>Enable Ctrl+Shift+I shortcut</td></tr><tr><td><code>enable_ctrl_shift_j</code></td><td>bool</td><td>true</td><td>Enable Ctrl+Shift+J shortcut</td></tr><tr><td><code>enable_ctrl_shift_c</code></td><td>bool</td><td>true</td><td>Enable Ctrl+Shift+C shortcut</td></tr><tr><td><code>enable_ctrl_u</code></td><td>bool</td><td>true</td><td>Enable Ctrl+U shortcut</td></tr><tr><td><code>enable_ctrl_r</code></td><td>bool</td><td>true</td><td>Enable Ctrl+R shortcut</td></tr></tbody></table>',15)])])}const p=e(a,[["render",l]]);export{u as __pageData,p as default};
